for (const { tokens, cost } of results) { console.log(cost, tokens.map((t) => t.surface));
} Parameters: Name Type Description text string Text to tokenize n number Number of results to return unique boolean Deduplicate results (default: false) costThreshold number | undefined Maximum cost difference from the best path (default: undefined) Returns: NbestResult[], where each NbestResult is { tokens: Token[], cost: number }

