The following example combines multiple character filters and token filters into a single pipeline: <?php $builder = new Lindera\TokenizerBuilder(); // Set mode and dictionary
$builder->setMode('normal');
$builder->setDictionary('embedded://ipadic'); // Preprocessing
$builder->appendCharacterFilter('unicode_normalize', ['kind' => 'nfkc']);
$builder->appendCharacterFilter( 'japanese_iteration_mark', ['normalize_kanji' => 'true', 'normalize_kana' => 'true']
);
$builder->appendCharacterFilter('mapping', ['mapping' => ['リンデラ' => 'lindera']]); // Postprocessing
$builder->appendTokenFilter('japanese_katakana_stem', ['min' => 3]);
$builder->appendTokenFilter('japanese_stop_tags', [ 'tags' => [ '接続詞', '助詞', '助詞,格助詞,一般', '助詞,格助詞,一般', '助詞,係助詞', '助詞,副助詞', '助詞,終助詞', '助詞,連体化', '助動詞', '記号', '記号,一般', '記号,読点', '記号,句点', '記号,空白', ],
]);
$builder->appendTokenFilter('lowercase'); // Build the tokenizer
$tokenizer = $builder->build(); // Tokenize
$text = 'Ｌｉｎｄｅｒａは形態素解析ｴﾝｼﾞﾝです。';
$tokens = $tokenizer->tokenize($text); foreach ($tokens as $token) { echo $token->surface . "\t" . implode(',', $token->details) . "\n";
} In this pipeline: unicode_normalize converts full-width characters to half-width (NFKC normalization) japanese_iteration_mark resolves iteration marks mapping replaces the specified strings japanese_katakana_stem stems katakana words japanese_stop_tags removes particles, auxiliary verbs, and symbols lowercase normalizes alphabetic characters to lowercase

