In browser environments, you must initialize the WASM module before using any Lindera functions. The default export __wbg_init handles this initialization. The recommended approach is to load dictionaries from OPFS rather than embedding them in the WASM binary: import __wbg_init, { TokenizerBuilder, loadDictionaryFromBytes } from 'lindera-wasm';
import { downloadDictionary, loadDictionaryFiles, hasDictionary } from 'lindera-wasm/opfs'; async function main() { // Initialize the WASM module (must be called once before using any API) await __wbg_init(); // Download dictionary if not cached if (!await hasDictionary("ipadic")) { await downloadDictionary( "https://github.com/lindera/lindera/releases/download/<version>/lindera-ipadic-<version>.zip", "ipadic", ); } // Load dictionary from OPFS const files = await loadDictionaryFiles("ipadic"); const dictionary = loadDictionaryFromBytes( files.metadata, files.dictTrie, files.dictValsIdx, files.dictVals, files.dictWordsIdx, files.dictWords, files.matrixMtx, files.charDef, files.unk, ); const builder = new TokenizerBuilder(); builder.setDictionaryInstance(dictionary); builder.setMode("normal"); const tokenizer = builder.build(); const tokens = tokenizer.tokenize("形態素解析を行います"); tokens.forEach(token => { console.log(`${token.surface}: ${token.details.join(',')}`); });
} main();

